                parse_says(9, favorable ? Players[faction_id].adj_leader :
                           Players[faction_id].adj_insult_leader, -1, -1);
                break;
            case 2:
                parse_says(5, favorable ? Players[faction_id].adj_faction :
                           Players[faction_id].adj_insult_faction, -1, -1);
                break;
            case 3:
                parse_says(9, favorable ? Players[faction_id].adj_leader :
                           Players[faction_id].adj_insult_leader, -1, -1);
