void __cdecl wait_loop() {
    if (IsMultiplayerNet != 0) {
        NetDaemonNet.net_tasks();
        int faction = ConsoleGlobal.faction_id_;
        if (UnkGlobal0093A934 == 0 && ConsoleControlTurnActive == 0 &&
            (NetDaemonNet.factions_waiting_mask() & (1u << faction)) == 0) {
            for (int other = 1; other < MaxPlayerNum; ++other) {
                faction = ConsoleGlobal.faction_id_;
                if (other != faction &&
                    (factions_status_byte(0) &
                     static_cast<uint8_t>(1u << other)) == 0 &&
                    FactionDiplomacyFlags[other] != 0) {
                    log_say("Initiating diplomatic channel", faction, other, 0);
                    const int open_faction = ConsoleGlobal.faction_id_;
                    if (NetDaemonNet.open_channel(open_faction, other) == 0) {
                        communicate(ConsoleGlobal.faction_id_, other, 0);
                    }
                }
            }
        }
    } else {
        wait_task();
    }
}


static void battle_plans_apply_selected_target(int faction_id,
                                                  int selected_base_id) {
    PlayerData &planner = PlayersData[faction_id];
    const Base &selected_base = Bases[selected_base_id];
    if (planner.x_target < 0) {
        return;
    }

    const Map &planned_tile = *map_loc(planner.x_target, planner.y_target);
    const Map &selected_tile = *map_loc(selected_base.x, selected_base.y);
    if (planned_tile.region == selected_tile.region) {
        return;
    }

    int vehicle_id;
    for (vehicle_id = 0; vehicle_id < GameDataStateStorage.fields_.vehicle_current_count_; ++vehicle_id) {
        Veh &vehicle = Vehs[vehicle_id];
        if (vehicle.faction_id == faction_id
            && (vehicle.state & VSTATE_UNK_40000) != 0) {
            vehicle.state &= ~(VSTATE_UNK_20000 | VSTATE_UNK_40000);
        }
    }
    planner.y_target = -1;
    planner.x_target = -1;
    planner.unk_72 = 0;
    planner.unk_71 = 0;
}

