    if (plan_a < 0 || plan_b < 0) {
        X_pops(BattlePlansInvalidPlanLabel, 0x100000,
                     FactionDiplomacyPortraits[faction_b], pop_wait);
        return;
    }

    PlanWindow.init(0);
