    PlayerData &faction_data = PlayersData[faction_id];

    faction_data.unk_28 = 0;
    faction_data.unk_13 = 0;
    faction_data.maint_cost_total = 0;
    faction_data.turn_commerce_income = 0;

    tech_effects(faction_id);

